1	// Package contractsentinel: strict detection of repeated JSON object members.
2	package contractsentinel
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"fmt"
8		"strconv"
9		"strings"
10	)
11	
12	// dupPathStep locates one level of a JSON value: a member step when the value
13	// was reached through an object member, or an index step when it is an
14	// element of an array.
15	type dupPathStep struct {
16		key   string // member name for an object step; "" for an array step
17		index int    // 0-based array index for an array step; -1 for an object step
18	}
19	
20	// duplicateMemberError records the repeated member name and the path of the
21	// object containing it. The path is schema-free; duplicateMemberMessage turns
22	// it into a user-facing message that names the rule id or check ruleId when
23	// the object is a rules/checks array entry.
24	type duplicateMemberError struct {
25		member string
26		path   []dupPathStep
27	}
28	
29	func (e *duplicateMemberError) Error() string {
30		return "duplicate JSON member " + strconv.Quote(e.member)
31	}
32	
33	// findDuplicateJSONMember scans data structurally and returns the first JSON
34	// object that repeats a member name. encoding/json keeps only the last value
35	// for a repeated key, so without this scan an invariants object writing the
36	// same invariant as false then true would import just the pass, and null
37	// then false would smuggle a defect past the non-boolean rejection.
38	//
39	// Member names are compared after JSON string decoding: "inv" written
40	// literally and the same name written with a Unicode escape collide.
41	// Comparison is case sensitive and never trims whitespace. Every object is
42	// checked, including the top-level object, nested objects and every array
43	// element; identical member names in different objects are normal. String
44	// values are consumed atomically, so text inside a string that looks like
45	// JSON is ordinary content and is never scanned.
46	//
47	// Malformed JSON yields nil here; json.Unmarshal remains the single source
48	// of syntax errors and runs right after this scan.
49	func findDuplicateJSONMember(data []byte) *duplicateMemberError {
50		dec := json.NewDecoder(bytes.NewReader(data))
51		// Keep number literals as text so oversized exponents cannot abort the
52		// structural scan; values themselves are irrelevant to duplicate keys.
53		dec.UseNumber()
54		dup, _ := scanJSONValue(dec, nil)
55		return dup
56	}
57	
58	// scanJSONValue consumes exactly one JSON value from dec and reports the
59	// first repeated object member at or below it. path locates the consumed
60	// value within its document.
61	func scanJSONValue(dec *json.Decoder, path []dupPathStep) (*duplicateMemberError, error) {
62		tok, err := dec.Token()
63		if err != nil {
64			return nil, err
65		}
66		delim, ok := tok.(json.Delim)
67		if !ok {
68			return nil, nil // null, bool, string or number: a complete scalar
69		}
70		switch delim {
71		case '{':
72			seen := make(map[string]bool)
73			for dec.More() {
74				keyTok, err := dec.Token()
75				if err != nil {
76					return nil, err
77				}
78				// Between More() and the value, Token can only be a member name.
79				key := keyTok.(string)
80				if seen[key] {
81					// path locates this object, not the repeated member; take a
82					// copy so later siblings cannot overwrite the retained path.
83					where := append([]dupPathStep(nil), path...)
84					return &duplicateMemberError{member: key, path: where}, nil
85				}
86				seen[key] = true
87				child := append(path, dupPathStep{key: key, index: -1})
88				dup, err := scanJSONValue(dec, child)
89				if err != nil {
90					return nil, err
91				}
92				if dup != nil {
93					return dup, nil
94				}
95			}
96			_, err := dec.Token() // consume '}'
97			return nil, err
98		case '[':
