1	// Command contractsentinel is the 智能合约审计与形式化验证流水线 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"flag"
7		"fmt"
8		"os"
9	
10		"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
11	)
12	
13	func main() {
14		command := "demo"
15		if len(os.Args) > 1 {
16			command = os.Args[1]
17		}
18		switch command {
19		case "demo":
20			runDemo()
21		case "version":
22			fmt.Println("contractsentinel 0.1.0")
23		case "audit":
24			runAudit(os.Args[2:])
25		case "report":
26			runReport(os.Args[2:])
27		case "diff":
28			runDiff(os.Args[2:])
29		case "help", "-h", "--help":
30			usage()
31		default:
32			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
33			usage()
34			os.Exit(2)
35		}
36	}
37	
38	func usage() {
39		fmt.Println("usage: contractsentinel [demo|version|audit|report|diff|help]")
40	}
41	
42	// runAudit parses an audit submission, builds the report and saves it.
43	func runAudit(args []string) {
44		fs := flag.NewFlagSet("audit", flag.ContinueOnError)
45		fs.SetOutput(os.Stderr)
46		inputPath := fs.String("input", "", "path to the audit input JSON file")
47		store := fs.String("store", "", "report store directory")
48		if err := fs.Parse(args); err != nil {
49			os.Exit(2)
50		}
51		if *inputPath == "" || *store == "" {
52			fmt.Fprintln(os.Stderr, "usage: contractsentinel audit --input <file> --store <dir>")
53			os.Exit(2)
54		}
55		data, err := os.ReadFile(*inputPath)
56		if err != nil {
57			fail("audit", err)
58		}
59		artifact, rules, invariants, checks, err := contractsentinel.ParseAuditInput(data)
60		if err != nil {
61			fail("audit", err)
62		}
63		report, err := contractsentinel.BuildReport(artifact, rules, invariants, checks)
64		if err != nil {
65			fail("audit", err)
66		}
67		if err := contractsentinel.SaveReport(*store, report); err != nil {
68			fail("audit", err)
69		}
70		printReport("audit", report)
71	}
72	
73	// runReport reads a saved report by id and prints it.
74	func runReport(args []string) {
75		fs := flag.NewFlagSet("report", flag.ContinueOnError)
76		fs.SetOutput(os.Stderr)
77		store := fs.String("store", "", "report store directory")
78		id := fs.String("id", "", "report id")
79		if err := fs.Parse(args); err != nil {
80			os.Exit(2)
81		}
82		if *store == "" || *id == "" {
83			fmt.Fprintln(os.Stderr, "usage: contractsentinel report --store <dir> --id <id>")
84			os.Exit(2)
85		}
86		report, err := contractsentinel.LoadReport(*store, *id)
87		if err != nil {
88			fail("report", err)
89		}
90		printReport("report", report)
91	}
92	
93	// runDiff compares two stored reports and prints the diff JSON.
94	func runDiff(args []string) {
95		fs := flag.NewFlagSet("diff", flag.ContinueOnError)
96		fs.SetOutput(os.Stderr)
97		store := fs.String("store", "", "report store directory")
98		before := fs.String("before", "", "baseline report id")
99		after := fs.String("after", "", "new report id")
100		if err := fs.Parse(args); err != nil {
101			os.Exit(2)
102		}
103		if *store == "" || *before == "" || *after == "" {
104			fmt.Fprintln(os.Stderr, "usage: contractsentinel diff --store <dir> --before <id> --after <id>")
105			os.Exit(2)
106		}
107		diff, err := contractsentinel.DiffStore(*store, *before, *after)
108		if err != nil {
109			fail("diff", err)
110		}
111		out, err := json.MarshalIndent(diff, "", "  ")
112		if err != nil {
113			fail("diff", err)
114		}
115		fmt.Println(string(out))
116	}
117	
118	// fail prints an error to stderr and exits with a non-zero status.
119	func fail(command string, err error) {
120		fmt.Fprintf(os.Stderr, "%s failed: %s\n", command, err)
121		os.Exit(1)
122	}
123	
124	// printReport writes the full report JSON to stdout.
125	func printReport(command string, report contractsentinel.Report) {
126		out, err := json.MarshalIndent(report, "", "  ")
127		if err != nil {
128			fail(command, err)
129		}
130		fmt.Println(string(out))
131	}
132	
133	func runDemo() {
134		artifact := contractsentinel.Artifact{Name: "Vault", ABI: "[{\"name\":\"withdraw\"}]", Bytecode: "0x6080", Source: "Vault.sol"}
135		rules := []contractsentinel.Rule{
136			{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw"},
137			{ID: "access-control", Kind: "static", Severity: "medium", Invariant: "owner-only-withdraw", RequiresABI: true},
138			{ID: "invariant-preserved", Kind: "symbolic", Severity: "critical", Invariant: "balance-monotonic"},
139		}
140		invariants := map[string]bool{"no-reentrant-withdraw": false, "owner-only-withdraw": true, "balance-monotonic": false}
141		findings, err := contractsentinel.Run(artifact, rules, invariants)
142		if err != nil {
143			fmt.Println("audit refused:", err)
144			return
145		}
146		for _, finding := range findings {
147			fmt.Printf("rule=%s severity=%s invariant=%s evidence=%s\n", finding.Rule, finding.Severity, finding.Invariant, finding.Evidence)
148		}
149		fmt.Printf("artifact=%s rules=%d findings=%d\n", artifact.Name, len(rules), len(findings))
150	}
151

