86			Rules:    mixedCheckRules(),
87			Checks: []cliWireCheck{
88				// 通过记录不带 note 字段：通过允许没有说明。
89				{ArtifactHash: hash, RuleID: "rule-pass", Version: "1.4.0", Status: contractsentinel.StatusPass},
90				{ArtifactHash: hash, RuleID: "rule-defect", Version: "2.0.1", Status: contractsentinel.StatusDefect, Note: defectNote},
91				{ArtifactHash: hash, RuleID: "rule-tool", Version: "3.0.0", Status: contractsentinel.StatusToolMissing, Note: "符号执行引擎未安装"},
92				{ArtifactHash: hash, RuleID: "rule-timeout", Version: "0.9.2", Status: contractsentinel.StatusTimeout, Note: "超过 60s 截止时间"},
93			},
94		}
95	}
