176		store := filepath.Join(work, "nested", "reports")
177	
178		stdout, stderr, code := runCLIAudit(t, bin, input, store)
179		if code != 0 {
180			t.Fatalf("legal import must succeed, exit=%d stderr=%s", code, stderr)
181		}
182		report := decodeReport(t, stdout)
183	
184		if !hex64.MatchString(report.ReportID) {
185			t.Fatalf("report id must be 64 lowercase hex chars, got %q", report.ReportID)
186		}
187		if report.Artifact.Name != "Vault" || report.Artifact.Hash != hash {
188			t.Fatalf("artifact header not bound to the submitted artifact: %+v", report.Artifact)
189		}
190	
191		statusByID := map[string]string{}
192		noteByID := map[string]string{}
193		for _, r := range report.Rules {
194			statusByID[r.ID] = r.Status
195			noteByID[r.ID] = r.Note
196		}
197		wantStatuses := map[string]string{
198			"rule-pass":      contractsentinel.StatusPass,
199			"rule-defect":    contractsentinel.StatusDefect,
200			"rule-tool":      contractsentinel.StatusToolMissing,
201			"rule-timeout":   contractsentinel.StatusTimeout,
202			"rule-unchecked": contractsentinel.StatusUnchecked,
203		}
204		if !reflect.DeepEqual(statusByID, wantStatuses) {
205			t.Fatalf("rule statuses = %+v, want %+v", statusByID, wantStatuses)
206		}
207		// 通过记录没有说明；其余三种结论的说明逐字保留（含中文、换行、前后空格）。
208		if noteByID["rule-pass"] != "" {
209			t.Errorf("pass rule note = %q, want empty", noteByID["rule-pass"])
210		}
211		if noteByID["rule-defect"] != defectNote {
212			t.Errorf("defect note = %q, want %q", noteByID["rule-defect"], defectNote)
213		}
214		if noteByID["rule-tool"] != "符号执行引擎未安装" {
215			t.Errorf("tool-missing note = %q", noteByID["rule-tool"])
216		}
217		if noteByID["rule-timeout"] != "超过 60s 截止时间" {
218			t.Errorf("timeout note = %q", noteByID["rule-timeout"])
219		}
220	
221		// 工具缺失与超时只是检查未完成：唯一缺陷只能来自 rule-defect。
222		if len(report.Findings) != 1 {
223			t.Fatalf("findings = %+v, want exactly one defect", report.Findings)
224		}
225		f := report.Findings[0]
226		if f.RuleID != "rule-defect" || f.Version != "2.0.1" || f.Severity != "high" || f.Invariant != "inv-defect" {
227			t.Fatalf("defect attribution = %+v", f)
228		}
229		if f.ArtifactHash != hash {
230			t.Fatalf("defect artifact hash = %q, want %q", f.ArtifactHash, hash)
231		}
232		if f.Evidence != defectNote {
233			t.Fatalf("evidence = %q, must equal the original note %q", f.Evidence, defectNote)
234		}
235		if f.Evidence == "invariant inv-defect does not hold" {
236			t.Fatal("imported defect evidence must not be replaced by the auto-generated template")
237		}
238	
239		// 成功时必须在指定存储目录落盘，且落盘内容与 stdout 报告完全一致。
240		savedPath := filepath.Join(store, report.ReportID+".json")
241		savedBytes, err := os.ReadFile(savedPath)
242		if err != nil {
243			t.Fatalf("report must be saved under the store directory: %v", err)
244		}
245		saved := decodeReport(t, string(savedBytes))
246		if !reflect.DeepEqual(saved, report) {
247			t.Fatalf("saved report does not match stdout report:\nsaved=%+v\nstdout=%+v", saved, report)
248		}
249		// 原始字节层面也要保留前后空格与中文，而不只是解码后凑巧相等。
250		if !strings.Contains(string(savedBytes), "  反例：攻击者可在 withdraw 中重入\\n  第二行证据  ") {
251			t.Fatalf("saved archive must preserve the raw note verbatim: %s", savedBytes)
252		}
253	}
254	
255	// --- 用返回的报告标识读回：不重新解释结论，归属与说明与提交成功时一致 ---
256	
257	func TestCLIAuditImportChecksReadbackByReportID(t *testing.T) {
258		bin := auditBinary(t)
259		work := t.TempDir()
260		hash := mixedArtifactHash(t)
261		input := writeStructInput(t, work, "in.json", mixedCheckInput(hash))
262		store := filepath.Join(work, "reports")
263	
264		stdout, stderr, code := runCLIAudit(t, bin, input, store)
265		if code != 0 {
266			t.Fatalf("legal import must succeed, exit=%d stderr=%s", code, stderr)
267		}
268		submitted := decodeReport(t, stdout)
269	
270		readStdout, readStderr, readCode := runCLIReport(t, bin, store, submitted.ReportID)
271		if readCode != 0 {
272			t.Fatalf("report read-back must succeed, exit=%d stderr=%s", readCode, readStderr)
273		}
274		loaded := decodeReport(t, readStdout)
275	
276		// 完整报告一致：标识、规则状态与说明、缺陷证据及归属逐项相同。
277		if !reflect.DeepEqual(loaded, submitted) {
278			t.Fatalf("read-back re-interpreted the submission:\nloaded=%+v\nsubmitted=%+v", loaded, submitted)
279		}
280		if loaded.ReportID != submitted.ReportID || loaded.Artifact != submitted.Artifact {
281			t.Fatalf("report id/artifact changed on read: %+v vs %+v", loaded.Artifact, submitted.Artifact)
282		}
283		for _, want := range submitted.Rules {
284			var got *contractsentinel.ReportRule
285			for i := range loaded.Rules {
286				if loaded.Rules[i].ID == want.ID {
287					got = &loaded.Rules[i]
288				}
289			}
290			if got == nil {
291				t.Fatalf("rule %s missing after read-back", want.ID)
292			}
293			if got.Status != want.Status || got.Note != want.Note || got.Version != want.Version {
294				t.Fatalf("rule %s changed on read: got %+v want %+v", want.ID, *got, want)
295			}
296		}
297		if len(loaded.Findings) != 1 {
298			t.Fatalf("findings after read-back = %d, want 1", len(loaded.Findings))
299		}
300		got := loaded.Findings[0]
301		want := submitted.Findings[0]
302		if got.RuleID != want.RuleID || got.Version != want.Version || got.Severity != want.Severity ||
303			got.Invariant != want.Invariant || got.ArtifactHash != want.ArtifactHash || got.Evidence != want.Evidence {
304			t.Fatalf("finding attribution changed on read:\ngot  %+v\nwant %+v", got, want)
305		}
306		if got.Evidence != defectNote {
307			t.Fatalf("evidence must stay the user note, got %q", got.Evidence)
308		}
309	}
310	
311	// --- 按规则归属：同名不变式、一个通过一个缺陷时，缺陷只属于后者 ---
312	
313	func TestCLIAuditImportChecksSharedInvariantAttribution(t *testing.T) {
314		bin := auditBinary(t)
315		work := t.TempDir()
316		a := mixedCheckArtifact()
317		hash := contractsentinel.ArtifactHash(contractsentinel.Artifact{
318			Name: a.Name, ABI: a.ABI, Bytecode: a.Bytecode, Source: a.Source,
319		})
320		const sharedInvariant = "shared-balance-invariant"
321		const note = "\t共享不变式反例：第二行\n"
322		in := cliWireInput{
323			Artifact: a,
324			Rules: []cliWireRule{
325				{ID: "rule-a", Kind: "static", Severity: "high", Invariant: sharedInvariant, Version: "7"},
326				{ID: "rule-b", Kind: "static", Severity: "low", Invariant: sharedInvariant, Version: "7"},
327			},
328			Checks: []cliWireCheck{
329				{ArtifactHash: hash, RuleID: "rule-a", Version: "7", Status: contractsentinel.StatusPass},
330				{ArtifactHash: hash, RuleID: "rule-b", Version: "7", Status: contractsentinel.StatusDefect, Note: note},
331			},
332		}
333		input := writeStructInput(t, work, "in.json", in)
334		store := filepath.Join(work, "reports")
335	
336		stdout, stderr, code := runCLIAudit(t, bin, input, store)
337		if code != 0 {
338			t.Fatalf("legal shared-invariant import must succeed, exit=%d stderr=%s", code, stderr)
339		}
340		report := decodeReport(t, stdout)
341	
342		statusByID := map[string]string{}
343		for _, r := range report.Rules {
344			statusByID[r.ID] = r.Status
345		}
346		if statusByID["rule-a"] != contractsentinel.StatusPass || statusByID["rule-b"] != contractsentinel.StatusDefect {
347			t.Fatalf("same invariant, different conclusions must be kept per rule: %+v", statusByID)
348		}
349		if len(report.Findings) != 1 {
350			t.Fatalf("exactly one rule defected, got findings %+v", report.Findings)
351		}
352		f := report.Findings[0]
353		if f.RuleID != "rule-b" {
354			t.Fatalf("defect must belong to rule-b only, got %q", f.RuleID)
355		}
356		if f.Version != "7" || f.Severity != "low" || f.Invariant != sharedInvariant || f.ArtifactHash != hash {
357			t.Fatalf("finding must carry rule-b's own binding, got %+v", f)
358		}
359		if f.Evidence != note {
360			t.Fatalf("evidence = %q, want the rule-b note %q", f.Evidence, note)
361		}
362		if f.Evidence == "invariant "+sharedInvariant+" does not hold" {
363			t.Fatal("evidence must not be replaced by a generic auto-generated note")
364		}
365	}
366	
367	// --- 任一记录产物哈希不匹配：整份拒绝，不产生任何部分报告或存储副作用 ---
368	
369	func TestCLIAuditImportChecksHashMismatchRejected(t *testing.T) {
370		bin := auditBinary(t)
371		work := t.TempDir()
372		hash := mixedArtifactHash(t)
373		in := mixedCheckInput(hash)
374		// 其余记录全部合法，仅工具缺失记录引用了另一份产物的哈希。
375		for i := range in.Checks {
376			if in.Checks[i].RuleID == "rule-tool" {
377				in.Checks[i].ArtifactHash = strings.Repeat("a", 64)
