package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	cs "github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
)

func main() {
	dir, _ := os.MkdirTemp("", "cs")
	defer os.RemoveAll(dir)
	a := cs.Artifact{Name: "Vault", ABI: "abi", Bytecode: "0x1", Source: "Vault.sol"}
	hash := cs.ArtifactHash(a)
	// legal pass rule report
	r := cs.Report{
		Artifact: cs.ReportArtifact{Name: "Vault", Hash: hash},
		Rules: []cs.ReportRule{
			{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1", Status: cs.StatusPass},
		},
	}
	if err := cs.SaveReport(dir, r); err != nil {
		panic(err)
	}
	id := cs.ReportID(r)
	path := filepath.Join(dir, id+".json")
	data, _ := os.ReadFile(path)
	// duplicate status: 发现缺陷 first, then the original 通过 (last wins)
	var raw map[string]json.RawMessage
	_ = json.Unmarshal(data, &raw)
	rulesJSON := string(raw["rules"])
	injected := rulesJSON[:len(rulesJSON)-2] + `,"status":"` + cs.StatusDefect + `","status":"` + cs.StatusPass + `"}]`
	raw["rules"] = json.RawMessage(injected)
	out, _ := json.Marshal(raw)
	os.WriteFile(path, out, 0o644)

	// LoadReport must reject as corrupt
	if _, err := cs.LoadReport(dir, id); err != nil {
		fmt.Printf("LoadReport rejected: %T: %v\n", err, err)
	} else {
		fmt.Println("LoadReport ACCEPTED (BAD)")
	}

	// diff must reject too
	if _, err := cs.DiffStore(dir, id, id); err != nil {
		fmt.Printf("DiffStore rejected: %T: %v\n", err, err)
	} else {
		fmt.Println("DiffStore ACCEPTED (BAD)")
	}

	// SaveReport of a different same-id-ish: build a fresh legal report and SaveReport against the dup file
	r2 := cs.Report{
		Artifact: cs.ReportArtifact{Name: "Vault", Hash: hash},
		Rules: []cs.ReportRule{
			{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1", Status: cs.StatusPass},
		},
	}
	r2.ReportID = id
	if err := cs.SaveReport(dir, r2); err != nil {
		fmt.Printf("SaveReport rejected existing dup archive: %T: %v\n", err, err)
	} else {
		fmt.Println("SaveReport treated dup archive as success (BAD)")
	}
	kept, _ := os.ReadFile(path)
	fmt.Printf("archive preserved: %v\n", string(kept) == string(out))

	// legal report under a different dir still loads
	dir2, _ := os.MkdirTemp("", "cs2")
	defer os.RemoveAll(dir2)
	if err := cs.SaveReport(dir2, r2); err != nil {
		panic(err)
	}
	if _, err := cs.LoadReport(dir2, id); err != nil {
		fmt.Println("legal report failed (BAD):", err)
	} else {
		fmt.Println("legal report still loads: OK")
	}
}
EOF
